function parseList(raw: string, locale: "en" | "es"): string[] {
  const normalized = locale === "es"
    ? raw.replace(/\s+u\s+/g, ", ").replace(/\s+o\s+/g, ", ").replace(/\s+y\s+/g, ", ")
