+    ] as const
+    : [
+      [/^an optional\s+(.+)$/i, "?"],
+      [/^optional(?:\s*\(none to many\))?\s+(.+)$/i, "*"],
+      [/^at least one\s+(.+)$/i, "+"],
+    ] as const;
+
+  for (const [pattern, multiplicity] of patterns) {
+    const match = trimmed.match(pattern);
+    if (!match) continue;
+    const name = match[1]!.trim();
+    if (!name) return null;
+    return { name, multiplicity };
+  }
+
+  return { name: trimmed };
